import { cacheTag } from 'next/cache'

export interface Post {
  id: number
  title: string
  content: string
}

// In-memory store standing in for a real database.
const posts: Post[] = []
let nextId = 1

export async function getPosts(): Promise<Post[]> {
  'use cache'
  cacheTag('posts')

  return [...posts]
}

export async function addPost(title: string, content: string): Promise<Post> {
  const post: Post = { id: nextId++, title, content }
  posts.push(post)
  return post
}

