'use server'

import { updateTag } from 'next/cache'
import { addPost } from '@/lib/posts'

export async function createPost(formData: FormData) {
  const title = formData.get('title')
  const content = formData.get('content')

  if (typeof title !== 'string' || title.trim() === '') {
    throw new Error('Title is required')
  }
  if (typeof content !== 'string' || content.trim() === '') {
    throw new Error('Content is required')
  }

  await addPost(title.trim(), content.trim())

  // updateTag expires the 'posts' tag immediately: the next request blocks
  // until fresh data is fetched, so the user never sees the stale list.
  // (revalidateTag would serve stale content while revalidating in the
  // background, which is not acceptable here.)
  updateTag('posts')
}

